var resetFlag = global.get("resetFlag");
var manualSwitch = global.get("switch"); // Fetch the manual switch status
var scadaswitch_status = global.get("scadaswitch");
//var scadaswitch_status = 1;



// Fetch previous values from the file
var previousValues = context.get('previousValues') || {};

// Use previous values if current values are null
obtainV = obtainV !== null ? obtainV : previousValues.voltage1;
obtainV2 = obtainV2 !== null ? obtainV2 : previousValues.voltage2;
obtainV3 = obtainV3 !== null ? obtainV3 : previousValues.voltage3;
obtainI = obtainI !== null ? obtainI : previousValues.current1;
obtainI2 = obtainI2 !== null ? obtainI2 : previousValues.current2;
obtainI3 = obtainI3 !== null ? obtainI3 : previousValues.current3;

var cb_decision;
var ov_status;
var oc_status;
var xx;

// Overvoltage and Undervoltage thresholds for voltage and current
var v_overvoltage = 30000;
var c_overvoltage = 6000;
var v_undervoltage = 200;
var c_undervoltage = 0.5;

// Update the previous values in the context
context.set('previousValues', {
    voltage1: obtainV,
    voltage2: obtainV2,
    voltage3: obtainV3,
    current1: obtainI,
    current2: obtainI2,
    current3: obtainI3
});
// Check reset flag and manual switch
if (resetFlag === "1") { // Reset flag is set
    global.set('cb_status', 'Closed'); // Reset the CB status to Closed
    msg.payload = 1; // Indicating circuit breaker is not tripped
    global.set('resetFlag', "0"); // Clear the reset flag
    return msg;
} else if (scadaswitch_status === 0) {
    manualSwitch === "0"
    cb_decision = 'Open';
    resetFlag = false;
    global.set('cb_status', cb_decision);
    msg.payload = 0; 

}
    else if (manualSwitch === "1") { // Switch is ON
    // Overvoltage & Undervoltage status
    ov_status = (obtainV > v_overvoltage || obtainV < v_undervoltage ||
        obtainV2 > v_overvoltage || obtainV2 < v_undervoltage ||
        obtainV3 > v_overvoltage || obtainV3 < v_undervoltage) ? 1 : 0;

    // Overcurrent & Undercurrent status
    oc_status = (obtainI > c_overvoltage || obtainI < c_undervoltage ||
        obtainI2 > c_overvoltage || obtainI2 < c_undervoltage ||
        obtainI3 > c_overvoltage || obtainI3 < c_undervoltage) ? 1 : 0;

    // Circuit breaker decision logic
    if (ov_status === 1 || oc_status === 1) {
        cb_decision = 'Open'; // Circuit breaker tripped
    } else {
        cb_decision = global.get('cb_status') === 'Open' ? 'Open' : 'Closed'; // Maintain Open if previously tripped
    }

    // Set global circuit breaker status
    global.set('cb_status', cb_decision);

    // Prepare message payload
    xx = cb_decision === 'Closed' ? 1 : 0; // 1 means not tripped, 0 means tripped
    msg.payload = xx;

} 

else { // Switch is RESET
    cb_decision = 'Open'; // Circuit breaker tripped
    global.set('cb_status', cb_decision);
    msg.payload = 0; // Indicating circuit breaker is tripped
}
return msg;

