var obtainV2 = global.get("voltage2");
var obtainV3 = global.get("voltage3");
var obtainI = global.get("current1");
var obtainI2 = global.get("current2");
var obtainI3 = global.get("current3");

const modbus = [
    ...floatToRegisters(obtainV),
    ...floatToRegisters(obtainV2),
    ...floatToRegisters(obtainV3),
    ...floatToRegisters(obtainI),
    ...floatToRegisters(obtainI2),
    ...floatToRegisters(obtainI3)
];

msg.payload = modbus;

return msg;
